        distances[idx] = l2_squared_u8(query, &vectors_flat[start..start + DIM]);
    }
}

#[inline(always)]
fn l2_squared_scalar(a: &[f32], b: &[f32]) -> f32 {
    let mut sum = 0.0f32;

    for idx in 0..DIM {
        let delta = a[idx] - b[idx];
        sum += delta * delta;
    }

    sum
}

