fn push_smallest(
    ids: &mut Vec<usize>,
    distances: &mut Vec<f32>,
    limit: usize,
    id: usize,
    distance: f32,
) {
    if ids.len() < limit {
        ids.push(id);
        distances.push(distance);
        return;
    }

    let mut worst_idx = 0usize;
    for idx in 1..distances.len() {
        if distances[idx] > distances[worst_idx] {
            worst_idx = idx;
        }
    }

    if distance < distances[worst_idx] {
        ids[worst_idx] = id;
        distances[worst_idx] = distance;
    }
}

